using System.IO;
using System.Linq;
namespace Touchfish {
public partial class PanelWindow {
 void VerifyGuestFirstTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();var previous=VerificationRun.FirstSeat;VerificationRun.FirstSeat=1;var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{
  lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="ROGUE");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Guest-first TCP peers connect");Check(match.FirstSeat==1&&guest.match.FirstSeat==1&&match.Players[0].Hand.Count==4&&guest.match.Players[1].Hand.Count==3,"Guest-first opening role and cards synchronize");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Second-player host confirms first");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Guest-first mulligan completes");Check(match.Active==1&&guest.match.Active==1&&guest.match.Players[1].Hand.Count==4&&match.Players[0].Hand.Count==5&&match.Players[0].Hand.Any(h=>h.CardId=="GAME_COIN"),"Guest gets first turn draw and host gets coin");Check(guest.matchViewSeat==1&&matchViewSeat==0&&guest.match.Players[0].Hand.Count==0&&guest.CanMatchInput()&&!CanMatchInput(),"Fixed viewpoints, hand privacy and turn input preserved");var rejected=lanAuthority.Execute(0,new LanCommand{Kind="end",Session=lanSession,Revision=lanRevision});Check(!rejected.Success&&match.Active==1,"Host cannot take guest first turn");guest.DoMatch("end");PumpLan(()=>match.Active==0&&!guest.lanWaiting,"Guest ends opening turn over TCP");Check(match.Players[0].Mana==1&&match.Players[0].Hand.Count==6&&CanMatchInput(),"Host second player's first turn draws and unlocks");guest.ApplyTheme(true,true);guest.ApplyMode(false);guest.RenderMatch();guest.ShowPage("match");guest.Opacity=1;guest.Render(Path.Combine(folder,"128-guest-first-fixed-view.png"));guest.Opacity=0;
 }finally{guest.LeaveLan();guest.Close();LeaveLan();VerificationRun.FirstSeat=previous;}}
}
}
